// Browser-local design constructor. No requests to people or xAI are made.
const builderStorageKey='ruly-bento-draft-v1';
const builderSizes={small:{label:'Квадрат',w:1,h:1},wide:{label:'Широкий',w:2,h:1},tall:{label:'Высокий',w:1,h:2},large:{label:'Крупный',w:2,h:2}};
const builderThemes={teal:'Тёмная бирюза',blue:'Голубой',cream:'Светлый',slate:'Серо-синий',graphite:'Графит'};
let builderMode=true;
const builderUndo=[];
let builderSaveFailed=false;
let builderStorageBlocked=false;
let builderLastSavedRaw=null;
let builderLastModel=null;
let builderStorageConflict=false;
root.children.forEach((n,i)=>{n.size=['wide','tall','small','small','small','small'][i];n.theme=['teal','cream','teal','blue','teal','slate'][i];});
function builderVisit(n,fn){fn(n);for(const c of n.children||[])builderVisit(c,fn);}
builderVisit(root,n=>{if(n!==root){n.size ||= 'small';n.theme ||= 'teal';}});
function builderValidTree(value){let count=0;const seen=new Set();function visit(n,depth){if(!n||typeof n!=='object'||++count>500||depth>20||typeof n.id!=='string'||!/^[a-zA-Z0-9_-]+$/.test(n.id)||seen.has(n.id)||typeof n.title!=='string'||!n.title.trim()||n.title.length>200)return false;seen.add(n.id);if(n.id!=='root'&&!Object.hasOwn(members,n.owner))return false;if(n.size&&!Object.hasOwn(builderSizes,n.size)||n.theme&&!Object.hasOwn(builderThemes,n.theme))return false;if(n.participants&&(!Array.isArray(n.participants)||n.participants.some(id=>!Object.hasOwn(members,id))))return false;if(n.due!==undefined&&typeof n.due!=='string'||n.description!==undefined&&typeof n.description!=='string'||n.result!==undefined&&typeof n.result!=='string')return false;if(n.children!==undefined)return Array.isArray(n.children)&&n.children.every(c=>visit(c,depth+1));return Object.hasOwn(statusNames,n.status);}return value?.id==='root'&&Array.isArray(value.children)&&visit(value,0);}
function builderRestore(value){for(const k of Object.keys(root))delete root[k];Object.assign(root,value);}
try{const raw=localStorage.getItem(builderStorageKey);builderLastSavedRaw=raw;const saved=JSON.parse(raw||'null');if(builderValidTree(saved)){builderRestore(saved);builderLastModel=JSON.stringify(root);}else if(raw)builderStorageBlocked=true;}catch{builderStorageBlocked=true;}
function builderPersist(){
  const hint=document.getElementById('saveHint');
  if(builderStorageBlocked||!builderValidTree(root)){hint.textContent=builderStorageConflict?'Черновик изменён в другой вкладке. Обновите страницу перед правками.':'Сохранение остановлено: прежний черновик сохранён без изменений.';return;}
  try{
    if(localStorage.getItem(builderStorageKey)!==builderLastSavedRaw){builderStorageBlocked=true;builderStorageConflict=true;builderPersist();return;}
    const json=JSON.stringify(root);
    if(json!==builderLastModel){localStorage.setItem(builderStorageKey,json);builderLastSavedRaw=json;builderLastModel=json;}
    builderSaveFailed=false;
  }catch{builderSaveFailed=true;}
  hint.innerHTML=`<i class="quiet-dot"></i>${builderSaveFailed?'Изменения только до обновления страницы':'Черновик сохраняется в этом браузере'} · Grok не подключён`;
}
window.addEventListener('storage',e=>{if(e.key===builderStorageKey||e.key===null)builderPersist();});
function builderCanEdit(){builderPersist();if(builderStorageBlocked){toast('Обновите страницу: сохранение в этой вкладке остановлено.');return false;}return true;}
function builderCanAdd(parent,amount=1){let count=0;builderVisit(root,()=>count++);if(count+amount>500){toast('В макете можно создать до 500 блоков.');return false;}if((findPath(parent.id)?.length||1)>20){toast('В макете можно создать до 20 вложенных уровней.');return false;}return true;}
function builderRemember(){builderUndo.push(JSON.stringify(root));if(builderUndo.length>25)builderUndo.shift();}
function builderPeople(n){const ids=new Set();builderVisit(n,x=>{for(const id of [...(x.owner?[x.owner]:[]),...(x.participants||[])]){if(members[id])ids.add(id);}});return{human:[...ids].filter(id=>members[id].type==='human'),bot:[...ids].filter(id=>members[id].type==='bot')};}
const builderPersonIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="3"/><path d="M5 21v-2a7 7 0 0 1 14 0v2"/></svg>';
const builderBotIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="7" width="16" height="14" rx="3"/><path d="M12 3v4M9 12v2M15 12v2M9 17h6M2 12h2M20 12h2"/></svg>';
function builderCounter(n,type){const count=builderPeople(n)[type].length;return`<button class="participant-square ${type} ${count?'lit':'unlit'}" data-people="${n.id}" data-type="${type}" aria-label="${type==='human'?'Люди':'Боты'}: ${count}. ${escapeHTML(n.title)}" title="${type==='human'?'Люди':'Боты'} в задаче и подзадачах"><span>${type==='human'?builderPersonIcon:builderBotIcon}</span><strong>${count}</strong></button>`;}
function builderCounters(n){return`<div class="participant-counters">${builderCounter(n,'human')}${builderCounter(n,'bot')}</div>`;}
card=function(n,i){const s=stats(n);const nested=Array.isArray(n.children);const size=builderSizes[n.size]?n.size:'small';const theme=builderThemes[n.theme]?n.theme:'teal';const signal=s.late?stateChip('overdue','Срок прошёл'):s.review?stateChip('review',`${s.review} на проверке`):nested?'':stateChip(n.status);return`<article class="task-block bento-card size-${size} theme-${theme}" data-card="${n.id}" style="--span-w:${builderSizes[size].w};--span-h:${builderSizes[size].h}"><button class="block-open" data-open="${n.id}" aria-label="${nested?'Открыть подзадачи: ':'Открыть задачу: '}${escapeHTML(n.title)}"></button><div class="block-top"><span class="block-index">${String(i+1).padStart(2,'0')}</span>${signal}<span class="enter-arrow" aria-hidden="true">↘</span></div><div class="block-title"><h2 title="${escapeHTML(n.title)}">${escapeHTML(n.title)}</h2><span class="block-subtitle">${nested?plural(n.children.length,'подзадача','подзадачи','подзадач'):'Конкретное поручение'}</span></div><div class="block-bottom"><div class="people-line">${builderCounters(n)}<span class="due">${escapeHTML(n.due||'Без срока')}</span></div><div class="bento-progress"><span>${nested?`${s.done} / ${s.total} выполнено`:statusNames[n.status]}</span><span>${nested?`${progress(s)}%`:members[n.owner].type==='bot'?'Grok':'Человек'}</span></div><div class="progress-track"><i style="width:${progress(s)}%"></i></div></div>${builderMode?`<div class="card-builder-tools"><button data-edit="${n.id}" title="Изменить блок" aria-label="Изменить блок: ${escapeHTML(n.title)}">${'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m16 3 5 5-12 12H4v-5L16 3zM14 5l5 5"/></svg>'}</button><button data-nest="${n.id}" title="Добавить подзадачу" aria-label="Добавить подзадачу в: ${escapeHTML(n.title)}">${svg('plus')}</button><span class="tools-divider"></span><button data-move="${n.id}" data-delta="-1" ${i===0?'disabled':''} aria-label="Переместить раньше: ${escapeHTML(n.title)}" title="Переместить раньше">←</button><button data-move="${n.id}" data-delta="1" ${i===activePath.at(-1).children.length-1?'disabled':''} aria-label="Переместить позже: ${escapeHTML(n.title)}" title="Переместить позже">→</button><button class="size-button" data-edit="${n.id}" title="Выбрать размер">${builderSizes[size].label}</button></div><button class="resize-handle" data-resize="${n.id}" aria-label="Изменить размер: ${escapeHTML(n.title)}" title="Потяните для изменения размера или используйте стрелки клавиатуры"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20h8v-8M16 20l4-4"/></svg></button>`:''}</article>`;};
const originalGroupView=groupView;
groupView=function(n){let html=originalGroupView(n);html=html.replace('<div class="heading-tools">',`<div class="heading-tools">${builderUndo.length?'<button class="undo-button" data-undo aria-label="Отменить последнее изменение" title="Отменить последнее изменение">↶</button>':''}<div class="mode-switch" aria-label="Режим"><button data-builder-mode="view" aria-pressed="${!builderMode}">Обзор</button><button data-builder-mode="build" aria-pressed="${builderMode}">Конструктор</button></div>`);html=html.replace('<section class="grid"',`<div class="builder-legend"><span><i class="legend-square human"></i>Люди</span><span><i class="legend-square bot"></i>AI-боты</span><small>Участники задачи и всех подзадач</small>${builderMode?'<span class="resize-hint">Потяните за угол блока ↘</span>':''}</div><section class="grid bento-grid"`);if(builderMode)html=html.replace('Каждый блок — следующий шаг внутри этой задачи','Создавайте блоки и переходите на следующий уровень');return html;};
const originalDetailView=detailView;
detailView=function(n){let html=originalDetailView(n);html=html.replace('<div class="detail-layout">',`<div class="leaf-constructor-bar">${builderCounters(n)}<span>Участники задачи</span><div><button class="secondary" data-edit="${n.id}">Изменить блок</button><button class="secondary" data-nest="${n.id}">${svg('plus')}Разбить на подзадачи</button></div></div><div class="detail-layout">`);return html;};
const originalRender=render;
render=function(focus=false){document.body.classList.add('bento');document.body.classList.toggle('is-building',builderMode);originalRender(focus);builderPersist();document.getElementById('footerHint').textContent=builderMode?'Размер, цвет и вложенность — у каждого блока свои.':'Нажмите на блок, чтобы перейти на следующий уровень.';};
function builderEditForm(node,parent){const isNew=!node;const n=node||{title:'',owner:'me',participants:[],size:'small',theme:'teal',due:'Без срока'};const direct=n.participants??[n.owner];openDialog(isNew?'Новый блок':'Настроить блок',`<form id="builderForm"><label>Название<input name="title" required maxlength="140" value="${escapeHTML(n.title)}" placeholder="Например, запустить продукт" autofocus></label><div class="form-pair"><label>Ответственный<select name="owner">${Object.entries(members).map(([id,m])=>`<option value="${id}" ${n.owner===id?'selected':''}>${escapeHTML(m.name)}</option>`).join('')}</select></label><label>Срок<input name="due" maxlength="40" value="${escapeHTML(n.due)}" placeholder="Например, 24 ноября"></label></div><fieldset class="size-options"><legend>Форма блока</legend>${Object.entries(builderSizes).map(([id,s])=>`<label><input type="radio" name="size" value="${id}" ${n.size===id?'checked':''}><span><i class="size-preview ${id}"></i>${s.label}</span></label>`).join('')}</fieldset><fieldset class="theme-options"><legend>Цвет блока</legend>${Object.entries(builderThemes).map(([id,name])=>`<label title="${name}"><input type="radio" name="theme" value="${id}" ${n.theme===id?'checked':''}><span class="theme-swatch theme-${id}"></span><span class="sr-only">${name}</span></label>`).join('')}</fieldset><fieldset class="member-options"><legend>Участники этого блока</legend><div>${Object.entries(members).map(([id,m])=>`<label class="member-choice"><input type="checkbox" name="participants" value="${id}" ${direct.includes(id)?'checked':''}>${avatar(id)}<span>${escapeHTML(m.name)}${m.type==='bot'?'<small>AI</small>':''}</span></label>`).join('')}</div></fieldset><p class="detail-note">Ответственный входит в состав. Счётчики учитывают участников всех подзадач без повторов.</p>${isNew?`<label class="check-label"><input type="checkbox" name="nested" ${parent===root?'checked':''}>Внутри будут подзадачи</label>`:''}<div class="dialog-actions"><button class="primary" type="submit">${isNew?'Создать блок':'Сохранить'}</button>${!isNew?'<button type="button" class="remove-button" data-delete-current>Удалить блок</button>':''}</div><p class="detail-note">Черновик хранится в этом браузере. Это макет, а не подключённая команда.</p></form>`);
  dialog.querySelector('[name=title]').oninput=e=>e.target.setCustomValidity('');
  dialog.querySelector('form').onsubmit=e=>{e.preventDefault();if(!builderCanEdit())return;const f=new FormData(e.target);const title=String(f.get('title')).trim();if(!title){const inp=dialog.querySelector('[name=title]');inp.setCustomValidity('Введите название');inp.reportValidity();return;}if(isNew&&!builderCanAdd(parent))return;builderRemember();const values={title,owner:String(f.get('owner')),due:String(f.get('due')).trim()||'Без срока',participants:f.getAll('participants'),size:String(f.get('size')),theme:String(f.get('theme'))};if(isNew){const id='block-'+crypto.randomUUID();parent.children.push({...values,id,...(f.get('nested')?{children:[]}:{status:'todo',description:'Опишите ожидаемый результат этой задачи.',result:''})});}else Object.assign(node,values);dialog.close();render();toast(isNew?'Новый блок добавлен':'Блок обновлён');};
  const remove=dialog.querySelector('[data-delete-current]');if(remove)remove.onclick=()=>{const path=findPath(node.id);const p=path.at(-2);builderRemember();p.children=p.children.filter(c=>c!==node);dialog.close();if(activePath.some(x=>x.id===node.id))go(p.id);else render();toast('Блок удалён. Можно отменить изменение кнопкой ↶.');};
}
addTask=function(){const parent=activePath.at(-1);if(parent.children)builderEditForm(null,parent);};
function builderNest(id){const path=findPath(id);const n=path?.at(-1);if(!n)return;if(!n.children){if(!builderCanAdd(n,2))return;builderRemember();const original=JSON.parse(JSON.stringify(n));original.id='step-'+crypto.randomUUID();original.size='small';n.children=[original];delete n.status;delete n.result;delete n.overdue;builderPersist();}go(id);builderEditForm(null,n);}
function builderSetSize(id,size){const n=findPath(id)?.at(-1);if(!n||n.size===size)return;const keepFocus=document.activeElement?.dataset?.resize===id;builderRemember();n.size=size;render();if(keepFocus)document.querySelector(`[data-resize="${id}"]`)?.focus({preventScroll:true});toast(`Размер: ${builderSizes[size].label.toLowerCase()}`);}
function builderParticipants(id,type){const n=findPath(id)?.at(-1);if(!n)return;const ids=builderPeople(n)[type];openDialog(type==='human'?'Люди в задаче':'AI-боты в задаче',`<p class="people-context">${escapeHTML(n.title)}</p>${ids.length?ids.map(id=>`<div class="member-row">${avatar(id)}<div>${escapeHTML(members[id].name)}<small>${escapeHTML(members[id].role)}</small></div>`).join(''):'<p>Участники этого типа пока не назначены.</p>'}<p>Состав этой задачи и всех вложенных подзадач. Без повторов.</p><button class="secondary" data-assign-current>Настроить участников</button>`);dialog.querySelector('[data-assign-current]').onclick=()=>{dialog.close();builderEditForm(n);};}
document.addEventListener('click',e=>{const mode=e.target.closest('[data-builder-mode]');if(mode){builderMode=mode.dataset.builderMode==='build';render();return;}const counter=e.target.closest('[data-people]');if(counter){e.stopPropagation();builderParticipants(counter.dataset.people,counter.dataset.type);return;}const edit=e.target.closest('[data-edit]');if(edit){builderEditForm(findPath(edit.dataset.edit).at(-1));return;}const nest=e.target.closest('[data-nest]');if(nest){builderNest(nest.dataset.nest);return;}const undo=e.target.closest('[data-undo]');if(undo&&builderUndo.length){builderRestore(JSON.parse(builderUndo.pop()));render();toast('Изменение отменено');return;}const move=e.target.closest('[data-move]');if(move&&!move.disabled){const path=findPath(move.dataset.move);const p=path.at(-2);const i=p.children.findIndex(n=>n.id===move.dataset.move);const next=i+Number(move.dataset.delta);if(next<0||next>=p.children.length)return;builderRemember();const [n]=p.children.splice(i,1);p.children.splice(next,0,n);render();return;}},false);
// Capture state before the base prototype changes result status.
document.addEventListener('click',e=>{if(e.target.closest('[data-edit],[data-add],[data-nest],[data-move],[data-undo],[data-accept],[data-return],[data-demo-result],[data-delete-current]')&&!builderCanEdit()){e.preventDefault();e.stopImmediatePropagation();return;}if(e.target.closest('[data-accept],[data-return],[data-demo-result]'))builderRemember();},true);
let resizeSession=null;
document.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-resize]');if(!handle||e.button!==0)return;e.preventDefault();if(!builderCanEdit())return;const node=findPath(handle.dataset.resize).at(-1);const rect=handle.closest('.bento-card').getBoundingClientRect();const grid=handle.closest('.grid');const columns=getComputedStyle(grid).gridTemplateColumns.split(' ').length;if(columns===1){builderEditForm(node);return;}resizeSession={id:node.id,handle,card:handle.closest('.bento-card'),x:e.clientX,y:e.clientY,w:builderSizes[node.size].w,h:builderSizes[node.size].h,cellW:(rect.width+(parseFloat(getComputedStyle(grid).gap)||16))/builderSizes[node.size].w,cellH:parseFloat(getComputedStyle(grid).gridAutoRows)+16,size:node.size};handle.setPointerCapture(e.pointerId);document.body.classList.add('is-resizing');});
document.addEventListener('pointermove',e=>{const s=resizeSession;if(!s)return;const w=Math.max(1,Math.min(2,s.w+Math.round((e.clientX-s.x)/s.cellW)));const h=Math.max(1,Math.min(2,s.h+Math.round((e.clientY-s.y)/s.cellH)));s.size=Object.keys(builderSizes).find(key=>builderSizes[key].w===w&&builderSizes[key].h===h);s.card.style.setProperty('--span-w',w);s.card.style.setProperty('--span-h',h);});
function builderEndResize(cancel=false){const s=resizeSession;if(!s)return;resizeSession=null;document.body.classList.remove('is-resizing');if(cancel)render();else builderSetSize(s.id,s.size);}
document.addEventListener('pointerup',()=>builderEndResize());document.addEventListener('pointercancel',()=>builderEndResize(true));
document.addEventListener('keydown',e=>{const handle=e.target.closest('[data-resize]');if(!handle)return;if(!builderCanEdit())return;const n=findPath(handle.dataset.resize).at(-1);const current=builderSizes[n.size];if(e.key==='Enter'||e.key===' '){e.preventDefault();builderEditForm(n);return;}if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const w=e.key==='ArrowLeft'?1:e.key==='ArrowRight'?2:current.w;const h=e.key==='ArrowUp'?1:e.key==='ArrowDown'?2:current.h;builderSetSize(n.id,Object.keys(builderSizes).find(key=>builderSizes[key].w===w&&builderSizes[key].h===h));});
render();
